# Email-Password Authentication with Hashing, Sessions & Rate Limiting

Here's a production-ready implementation using Node.js/Express with SQLite:

```javascript
// server.js
import express from 'express';
import sqlite3 from 'sqlite3';
import bcrypt from 'bcrypt';
import crypto from 'crypto';
import { body, validationResult } from 'express-validator';

const app = express();
app.use(express.json());

// Database setup
const db = new sqlite3.Database(':memory:');

db.serialize(() => {
  db.run(`
    CREATE TABLE users (
      id INTEGER PRIMARY KEY,
      email TEXT UNIQUE NOT NULL,
      password_hash TEXT NOT NULL,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP
    )
  `);

  db.run(`
    CREATE TABLE sessions (
      id TEXT PRIMARY KEY,
      user_id INTEGER NOT NULL,
      expires_at DATETIME NOT NULL,
      FOREIGN KEY(user_id) REFERENCES users(id)
    )
  `);

  db.run(`
    CREATE TABLE login_attempts (
      id INTEGER PRIMARY KEY,
      email TEXT NOT NULL,
      attempted_at DATETIME DEFAULT CURRENT_TIMESTAMP,
      success BOOLEAN NOT NULL
    )
  `);
});

// Rate limiting: check failed attempts in last 15 minutes
const isRateLimited = (email) => {
  return new Promise((resolve) => {
    const fifteenMinutesAgo = new Date(Date.now() - 15 * 60 * 1000);
    db.get(
      `SELECT COUNT(*) as count FROM login_attempts 
       WHERE email = ? AND success = 0 AND attempted_at > ?`,
      [email, fifteenMinutesAgo.toISOString()],
      (err, row) => {
        resolve(row.count >= 5); // Max 5 failed attempts
      }
    );
  });
};

const recordLoginAttempt = (email, success) => {
  db.run(
    `INSERT INTO login_attempts (email, success) VALUES (?, ?)`,
    [email, success ? 1 : 0]
  );
};

// Password hashing
const hashPassword = async (password) => {
  return bcrypt.hash(password, 12);
};

const verifyPassword = async (password, hash) => {
  return bcrypt.compare(password, hash);
};

// Session management
const createSession = (userId) => {
  const sessionId = crypto.randomBytes(32).toString('hex');
  const expiresAt = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000); // 7 days

  return new Promise((resolve, reject) => {
    db.run(
      `INSERT INTO sessions (id, user_id, expires_at) VALUES (?, ?, ?)`,
      [sessionId, userId, expiresAt.toISOString()],
      (err) => {
        if (err) reject(err);
        else resolve({ sessionId, expiresAt });
      }
    );
  });
};

const validateSession = (sessionId) => {
  return new Promise((resolve) => {
    db.get(
      `SELECT user_id FROM sessions WHERE id = ? AND expires_at > ?`,
      [sessionId, new Date().toISOString()],
      (err, row) => {
        resolve(row?.user_id || null);
      }
    );
  });
};

// Middleware to check auth
const authMiddleware = async (req, res, next) => {
  const sessionId = req.headers.authorization?.split(' ')[1];
  if (!sessionId) {
    return res.status(401).json({ error: 'No session provided' });
  }

  const userId = await validateSession(sessionId);
  if (!userId) {
    return res.status(401).json({ error: 'Invalid or expired session' });
  }

  req.userId = userId;
  next();
};

// SIGNUP
app.post(
  '/signup',
  body('email').isEmail(),
  body('password').isLength({ min: 8 }),
  async (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const { email, password } = req.body;

    try {
      const passwordHash = await hashPassword(password);

      db.run(
        `INSERT INTO users (email, password_hash) VALUES (?, ?)`,
        [email, passwordHash],
        async (err) => {
          if (err) {
            if (err.message.includes('UNIQUE')) {
              return res.status(409).json({ error: 'Email already registered' });
            }
            return res.status(500).json({ error: 'Database error' });
          }

          // Get the new user ID
          db.get(
            `SELECT id FROM users WHERE email = ?`,
            [email],
            async (err, user) => {
              const { sessionId, expiresAt } = await createSession(user.id);
              res.status(201).json({
                message: 'Signup successful',
                sessionId,
                expiresAt,
              });
            }
          );
        }
      );
    } catch (err) {
      res.status(500).json({ error: 'Server error' });
    }
  }
);

// LOGIN
app.post(
  '/login',
  body('email').isEmail(),
  body('password').notEmpty(),
  async (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const { email, password } = req.body;

    // Rate limiting check
    if (await isRateLimited(email)) {
      recordLoginAttempt(email, false);
      return res.status(429).json({
        error: 'Too many failed attempts. Try again in 15 minutes.',
      });
    }

    db.get(`SELECT id, password_hash FROM users WHERE email = ?`, [email], async (err, user) => {
      if (!user) {
        recordLoginAttempt(email, false);
        return res.status(401).json({ error: 'Invalid email or password' });
      }

      const isValid = await verifyPassword(password, user.password_hash);
      if (!isValid) {
        recordLoginAttempt(email, false);
        return res.status(401).json({ error: 'Invalid email or password' });
      }

      recordLoginAttempt(email, true);
      const { sessionId, expiresAt } = await createSession(user.id);
      res.json({
        message: 'Login successful',
        sessionId,
        expiresAt,
      });
    });
  }
);

// Protected route example
app.get('/profile', authMiddleware, (req, res) => {
  res.json({ userId: req.userId, message: 'This is your profile' });
});

// LOGOUT
app.post('/logout', authMiddleware, (req, res) => {
  const sessionId = req.headers.authorization.split(' ')[1];
  db.run(`DELETE FROM sessions WHERE id = ?`, [sessionId], () => {
    res.json({ message: 'Logged out successfully' });
  });
});

app.listen(3000, () => console.log('Server running on port 3000'));
```

## Key Features

| Feature | Implementation |
|---------|---|
| **Password Hashing** | bcrypt with 12 salt rounds (industry standard) |
| **Sessions** | Random 256-bit tokens, 7-day expiration, validated on each request |
| **Rate Limiting** | Max 5 failed attempts per 15 minutes per email |
| **Validation** | Email format, 8+ char passwords via express-validator |
| **Security** | No passwords logged, constant-time comparison (bcrypt), unique session IDs |

## Example Usage

```bash
# Signup
curl -X POST http://localhost:3000/signup \
  -H "Content-Type: application/json" \
  -d '{"email":"user@example.com","password":"securepass123"}'

# Returns: {"sessionId":"abc123...","expiresAt":"2026-11-30T..."}

# Login
curl -X POST http://localhost:3000/login \
  -H "Content-Type: application/json" \
  -d '{"email":"user@example.com","password":"securepass123"}'

# Access protected route
curl http://localhost:3000/profile \
  -H "Authorization: Bearer abc123..."
```

**Production considerations:** Use PostgreSQL instead of SQLite, add HTTPS, implement CSRF protection, clean expired sessions periodically, store sessions in Redis, add email verification, and implement account lockout after repeated failures.
